// CSD_RATIONALE_BEGIN
// Root-cause analysis of accuracy plateau at ~49.7%:
//
// Main failure mode (135/300): syntax_valid_wrong — the model generates structurally
// correct SQL with wrong identifiers (hallucinated table/column names not in the schema,
// or plausible-sounding names that don't match the question's schema context).
//
// Secondary failure mode (25/300): repetition loops (Gelderland example) where the
// model hallucinated "country.language" conditions and repeated them hundreds of times.
//
// The standard GroupBoostedConstrainedStep(6.0) loop approach (attempt 9, best at 49.7%)
// provides hard grammar masking and soft schema-token boosting but cannot detect and
// repair hallucinated identifiers that ARE grammar-valid but NOT grounded in the schema.
//
// Fix: Use RegenerateUnitOnGroundingFailure as the primary generation engine for Phase 3.
// This helper:
//   1. Generates SQL tokens under dead-end-avoiding constrained steps (hard grammar mask)
//   2. Detects unit boundaries when a schema-symbol (table/column identifier) completes
//   3. Checks if the identifier is grounded in the prompt (schema context)
//   4. If ungrounded, rolls back to the last accepted checkpoint and resamples (≤3 retries)
//   5. Accepts the unit after maxRetries to preserve termination
//
// This directly fixes the root cause: "FROM country" when the schema only has "city",
// "FROM model_list m" when the join structure differs, etc.
//
// Key structural decisions:
//   - 5-step preamble: let model emit "SQL: " naturally (empirically best from attempt 9)
//   - Force OpenConstrainedSpan if preamble doesn't naturally emit "<<"
//   - RegenerateUnitOnGroundingFailure with budget=maxSteps-steps-2, retries=3, rollback=10
//     to give maximum budget for grounded generation with graceful fallback
//   - Use constrainedPrompt = prompt + stablePrefix so grounding checks have full context
//   - Phase 4 close: direct CloseConstrainedSpan if complete, CloseSpanWithinBudget otherwise
//   - Reserve 2 steps for close to ensure span is always terminated
//
// Guidance string from attempt 9 (empirically best, unchanged).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble loop, !insideConstrainedOut throughout):
//   The loop runs only while !insideConstrainedOut. If RenderedEndsWith(generated, "<<")
//   fires, we set currentConstrainedOut := [] which satisfies parser.IsValidPrefix([])
//   by method precondition. Otherwise insideConstrainedOut stays false (implication
//   vacuously true). EOS break leaves state unchanged. ✓
//
// Phase 2 (OpenConstrainedSpan):
//   Only runs when !insideConstrainedOut. Sets currentConstrainedOut := []; satisfies
//   parser.IsValidPrefix([]) by method precondition. ✓
//
// Phase 3 (RegenerateUnitOnGroundingFailure):
//   Only executes when insideConstrainedOut=true. Postcondition of this helper guarantees
//   parser.IsValidPrefix(resultConstrained). We assign currentConstrainedOut := resultConstrained,
//   preserving the invariant. insideConstrainedOut remains true. ✓
//
// Phase 4a (CloseConstrainedSpan):
//   Sets insideConstrainedOut := false and currentConstrainedOut := []; implication
//   becomes vacuously true. ✓
//
// Phase 4b (CloseSpanWithinBudget):
//   Postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each iteration increments steps by 1 and grows generated by at most 1
//   (0 on EOS break, 1 on non-EOS token). |generated| - |generatedPrefix| <= steps. ✓
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//
// Phase 3: budgetForGen = maxSteps - steps_old - 2. After the call:
//   |resultConstrained| <= |currentConstrainedOut_old| + budgetForGen (postcondition).
//   |generated|_new = |stablePrefix| + |resultConstrained|
//                   = (|generated|_old - |currentConstrainedOut|_old) + |resultConstrained|
//                   <= |generated|_old + budgetForGen
//                   <= |generatedPrefix| + steps_old + budgetForGen
//                   = |generatedPrefix| + steps_new. ✓
//   steps_new = steps_old + budgetForGen = maxSteps - 2 <= maxSteps. ✓
//
// Phase 4a: CloseConstrainedSpan appends at most 1 ">>" token, steps += 1.
//   |generated|_new <= |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//
// Phase 4b: CloseSpanWithinBudget with budget = maxSteps - steps (≥ 1).
//   Postcondition: |generatedOut| <= |generated| + budget. steps := maxSteps.
//   |generated|_new <= |generated|_old + (maxSteps - steps_old) = |generatedPrefix| + maxSteps
//                    = |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output SQL: <<query>> where the query is a valid SQL SELECT statement using only the given schema tables and columns. Put your answer between << and >>. No explanation.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) to let model emit "SQL: "
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Grounding-aware SQL generation via RegenerateUnitOnGroundingFailure.
// Reserve 2 steps for the close phase. This helper detects when a table/column
// identifier is not grounded in the prompt and rolls back + resamples, directly
// fixing hallucinated-identifier errors (the primary failure mode).
if insideConstrainedOut && maxSteps >= steps + 2 {
  var budgetForGen: nat := maxSteps - steps - 2;
  var stableLen: nat := |generated| - |currentConstrainedOut|;
  var stablePrefix := generated[..stableLen];
  var constrainedPrompt := prompt + stablePrefix;
  var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
    lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, budgetForGen, 3, 10
  );
  generated := stablePrefix + resultConstrained;
  currentConstrainedOut := resultConstrained;
  steps := steps + budgetForGen;
}

// Phase 4: Close the constrained span.
// Direct close if the current prefix is already complete; otherwise use
// CloseSpanWithinBudget to advance to the longest complete point and close there.
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }
}

